const noteHoldPassed = `-- name: NoteHoldPassed :execrows
UPDATE deliveries
SET detail = $4
WHERE id = $1 AND lease_owner = $2 AND attempts = $3 AND state = 'uncertain'
  AND detail IS DISTINCT FROM $4
`

type NoteHoldPassedParams struct {
	ID         string
	LeaseOwner *string
	Attempts   int32
	Detail     *string
}

// Records, once, that an uncertain delivery's hold is over. updated_at stays: the hold is counted
// from it. Zero rows when the note is already there, so the caller announces it once.
func (q *Queries) NoteHoldPassed(ctx context.Context, arg NoteHoldPassedParams) (int64, error) {
	result, err := q.db.Exec(ctx, noteHoldPassed,
		arg.ID,
		arg.LeaseOwner,
		arg.Attempts,
		arg.Detail,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const refreshSessionStatus = `-- name: RefreshSessionStatus :exec
UPDATE sessions
SET status = CASE WHEN EXISTS (
        SELECT 1 FROM deliveries d
        WHERE d.session_id = sessions.id AND d.state IN ('recorded', 'sending', 'delivered'))
    THEN 'active' ELSE 'idle' END,
    started_at = coalesce(started_at, now())
WHERE sessions.id = $1 AND sessions.status IN ('pending', 'active', 'idle')
`

func (q *Queries) RefreshSessionStatus(ctx context.Context, id string) error {
	_, err := q.db.Exec(ctx, refreshSessionStatus, id)
	return err
}

const replaceDeliveryKagentSession = `-- name: ReplaceDeliveryKagentSession :execrows
UPDATE agent_bindings b
SET kagent_session_id = NULL, kagent_request_id = $1, standing_hash = NULL,
    updated_at = now()
FROM deliveries d
WHERE d.id = $2 AND d.lease_owner = $3 AND d.attempts = $4
  AND b.session_id = d.session_id
  AND b.kagent_session_id IS NOT DISTINCT FROM $5::text
  AND b.kagent_request_id IS NOT DISTINCT FROM $6::text
`

type ReplaceDeliveryKagentSessionParams struct {
	NewRequestID *string
	ID           string
	LeaseOwner   *string
	Attempts     int32
	OldSessionID *string
	OldRequestID *string
}

// Drops a kagent Session that kagent no longer has, so the next create runs under a new request
// id. Fenced on the delivery's claim and on the Session being replaced.
func (q *Queries) ReplaceDeliveryKagentSession(ctx context.Context, arg ReplaceDeliveryKagentSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, replaceDeliveryKagentSession,
		arg.NewRequestID,
		arg.ID,
		arg.LeaseOwner,
		arg.Attempts,
		arg.OldSessionID,
		arg.OldRequestID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setDeliveryKagentSession = `-- name: SetDeliveryKagentSession :execrows
UPDATE agent_bindings b
SET kagent_session_id = $1, updated_at = now()
FROM deliveries d
WHERE d.id = $2 AND d.lease_owner = $3 AND d.attempts = $4
  AND b.session_id = d.session_id
  AND b.kagent_session_id IS NULL
  AND b.kagent_request_id IS NOT DISTINCT FROM $5::text
`

type SetDeliveryKagentSessionParams struct {
	KagentSessionID *string
	ID              string
	LeaseOwner      *string
	Attempts        int32
	RequestID       *string
}

// Stores the kagent Session the create returned. Fenced on the delivery's claim and on the
// request id the create used, so a claimer that lost its lease, or one whose request id has since
// been replaced, changes nothing.
func (q *Queries) SetDeliveryKagentSession(ctx context.Context, arg SetDeliveryKagentSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, setDeliveryKagentSession,
		arg.KagentSessionID,
		arg.ID,
		arg.LeaseOwner,
		arg.Attempts,
		arg.RequestID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setSessionCancelled = `-- name: SetSessionCancelled :one
UPDATE sessions
SET status = 'cancelled', completed_at = coalesce(completed_at, now())
WHERE id = $1 AND status NOT IN ('completed', 'failed', 'cancelled')
RETURNING id
`

// The cancelled status is final (RefreshSessionStatus leaves it alone). Nothing changes once the
// session is finished.
func (q *Queries) SetSessionCancelled(ctx context.Context, id string) (string, error) {
	row := q.db.QueryRow(ctx, setSessionCancelled, id)
	var id_2 string
	err := row.Scan(&id_2)
	return id_2, err
}
